#include <iostream>#include <string>using namespace std;class Staff {protected:    string name;    int id;    double basic;public:    Staff(string n, int i, double b) {        name = n;        id = i;        basic = b;    }    virtual double pay() = 0;    virtual void display() {        cout << name << " " << id << " " << pay() << endl;    }    virtual ~Staff() {}};class Professor : public Staff {    double research;public:    Professor(string n, int i, double b, double r)        : Staff(n, i, b) {        research = r;    }    double pay() override {        return basic + basic * 0.42 + research;    }};class LabAssistant : public Staff {public:    LabAssistant(string n, int i, double b)        : Staff(n, i, b) {}    double pay() override {        return basic + basic * 0.42;    }};class GuestFaculty : public Staff {    double hours, rate;public:    GuestFaculty(string n, int i, double h, double r)        : Staff(n, i, 0) {        hours = h;        rate = r;    }    double pay() override {        return hours * rate;    }};int main() {    Staff* s[3];    s[0] = new Professor("Ravi", 101, 30000, 5000);    s[1] = new LabAssistant("Kiran", 102, 20000);    s[2] = new GuestFaculty("Anu", 103, 40, 500);    for (int i = 0; i < 3; i++) {        s[i]->display();        delete s[i];    }    return 0;}